**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int sumaCyfr(int n) {
    int s = 0;
    while (n > 0) {
        s += n % 10;
        n /= 10;
    }
    return s;
}

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int freq[10] = {0};

    cout << "a) Pierwiastki cyfrowe:" << endl;
    while (plik >> liczba) {
        cout << liczba << ": ";
        int n = liczba;
        string s = to_string(n);
        for (int i = 0; i < (int)s.length(); i++) {
            if (i > 0) cout << "+";
            cout << s[i];
        }
        n = sumaCyfr(n);
        cout << "=" << n;
        while (n >= 10) {
            cout << " -> ";
            string s2 = to_string(n);
            for (int i = 0; i < (int)s2.length(); i++) {
                if (i > 0) cout << "+";
                cout << s2[i];
            }
            n = sumaCyfr(n);
            cout << "=" << n;
        }
        cout << " -> " << n << endl;
        freq[n]++;
    }

    cout << endl << "b) Grupowanie:" << endl;
    for (int i = 1; i <= 9; i++) {
        if (freq[i] > 0) {
            cout << "  pierwiastek " << i << ": " << freq[i];
            if (freq[i] == 1) cout << " liczba" << endl;
            else cout << " liczby" << endl;
        }
    }

    cout << endl << "c) Najczestszy: pierwiastek ";
    int maxRoot = 1;
    for (int i = 2; i <= 9; i++) {
        if (freq[i] > freq[maxRoot]) maxRoot = i;
    }
    cout << maxRoot << " (" << freq[maxRoot] << " liczby)" << endl;
    return 0;
}
```

**Wyjasnienie**: Pierwiastek cyfrowy to wynik wielokrotnego sumowania cyfr az do jednej cyfry. Zliczamy wystapienia w tablicy `freq[1..9]` (pierwiastek 0 nie wystapi dla liczb dodatnich). Szukamy max z preferencja mniejszego indeksu.

